
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_kt3_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_kt3", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.786016255222938e+00, -4.697973951979135e+00, -4.574863886591618e+00, -4.404882191769959e+00, -4.174477146768043e+00, -3.870542097736196e+00, -3.485564920387402e+00, -3.027423998016239e+00, -2.533173000366978e+00, -2.057463557851325e+00, -1.455909439077734e+00, -8.023332676874183e-01, -6.820296044239069e-01, -5.590726057851996e-01, -3.946746063936093e-01, -2.447721433482893e-01, -1.382978479218567e-01, -5.726824918903548e-02, -1.256038400070998e-02, -1.408186022839406e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


